import java.io.*;
import java.util.*;

public class Main {
    private static final InputStream IN = System.in;
    private static final byte[] BUF = new byte[1 << 16];
    private static int len = 0, ptr = 0;

    private static int read() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    private static int skipSpaces() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        return c;
    }

    private static long nextLong() throws IOException {
        int c = skipSpaces();
        boolean negative = c == '-';
        if (negative) c = read();
        long value = 0;
        while (c >= '0' && c <= '9') {
            value = value * 10 + (c - '0');
            c = read();
        }
        return negative ? -value : value;
    }

    private static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt(), k = nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = nextInt();
        int[] sorted = a.clone();
        Arrays.sort(sorted);
        int size = 0;
        for (int i = 0; i < n; i++) if (i == 0 || sorted[i] != sorted[i - 1]) sorted[size++] = sorted[i];
        int[] values = Arrays.copyOf(sorted, size);
        int[] rank = new int[n];
        for (int i = 0; i < n; i++) rank[i] = Arrays.binarySearch(values, a[i]) + 1;
        int[] tree = new int[size + 1]; // Fenwick tree of counts per rank in the current window
        int top = 1;
        while (top * 2 <= size) top *= 2;
        for (int i = 0; i < m; i++) update(tree, rank[i], 1);
        StringBuilder out = new StringBuilder();
        out.append(values[kth(tree, top, k)]);
        for (int i = m; i < n; i++) {
            update(tree, rank[i - m], -1);
            update(tree, rank[i], 1);
            out.append(' ').append(values[kth(tree, top, k)]);
        }
        System.out.println(out);
    }

    private static void update(int[] tree, int index, int delta) {
        for (; index < tree.length; index += index & -index) tree[index] += delta;
    }

    // Binary lifting: the longest prefix of ranks with count < k; returns its length, the k-th smallest's rank - 1.
    private static int kth(int[] tree, int top, int k) {
        int index = 0, target = k;
        for (int step = top; step > 0; step >>= 1) {
            int following = index + step;
            if (following < tree.length && tree[following] < target) {
                index = following;
                target -= tree[following];
            }
        }
        return index;
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

// next returns the next whitespace-separated token of the input.
func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	token := next()
	negative := len(token) > 0 && token[0] == '-'
	if negative {
		token = token[1:]
	}
	value := 0
	for _, c := range token {
		value = value*10 + int(c-'0')
	}
	if negative {
		return -value
	}
	return value
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m, k := nextInt(), nextInt(), nextInt()
	a := make([]int, n)
	for i := range a {
		a[i] = nextInt()
	}
	values := slices.Clone(a)
	slices.Sort(values)
	values = slices.Compact(values)
	size := len(values)
	rank := make([]int, n)
	for i, v := range a {
		r, _ := slices.BinarySearch(values, v)
		rank[i] = r + 1
	}
	tree := make([]int32, size+1) // Fenwick tree of counts per rank in the current window
	update := func(index int, delta int32) {
		for ; index <= size; index += index & -index {
			tree[index] += delta
		}
	}
	top := 1
	for top*2 <= size {
		top *= 2
	}
	// Binary lifting: the longest prefix of ranks with count < k; the next rank is the k-th smallest.
	kth := func() int {
		index, target := 0, int32(k)
		for step := top; step > 0; step >>= 1 {
			following := index + step
			if following <= size && tree[following] < target {
				index = following
				target -= tree[following]
			}
		}
		return values[index]
	}
	for i := 0; i < m; i++ {
		update(rank[i], 1)
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	w.WriteString(strconv.Itoa(kth()))
	for i := m; i < n; i++ {
		update(rank[i-m], -1)
		update(rank[i], 1)
		w.WriteByte(' ')
		w.WriteString(strconv.Itoa(kth()))
	}
	w.WriteByte('\n')
}
